const $=id=>document.getElementById(id);
const name=x=>String(x||'').replaceAll('_',' ');
const tone=x=>{x=String(x||'').toLowerCase();return x.includes('bull')||x.includes('long')?'bullish':x.includes('bear')||x.includes('short')?'bearish':'neutral'};
const esc=x=>String(x??'—').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));
const fmt=x=>x==null||Number.isNaN(Number(x))?'—':Number(x).toLocaleString(undefined,{maximumFractionDigits:2});
const dateFmt=x=>x?new Date(x).toLocaleString():'';
function showError(e){$('error').textContent=e?.message||String(e)}
